def choose_move(observation):
    def clamp(v):
        return -1 if v < -0.5 else (1 if v > 0.5 else 0)

    def get_pos(obj):
        if isinstance(obj, dict):
            if 'pos' in obj:
                p = obj.get('pos')
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    return p[0], p[1]
            x = obj.get('x')
            y = obj.get('y')
            if x is not None and y is not None:
                return x, y
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def find_self(obs):
        for key in ('self', 'agent', 'player', 'me', 'unit'):
            p = get_pos(obs.get(key))
            if p is not None:
                return p
        for key in ('position', 'pos', 'location'):
            p = get_pos(obs.get(key))
            if p is not None:
                return p
        return (0, 0)

    def iter_positions(container):
        if container is None:
            return
        if isinstance(container, dict):
            for v in container.values():
                p = get_pos(v)
                if p is not None:
                    yield p
                elif isinstance(v, (list, tuple)):
                    for item in v:
                        p2 = get_pos(item)
                        if p2 is not None:
                            yield p2
        elif isinstance(container, (list, tuple)):
            for v in container:
                p = get_pos(v)
                if p is not None:
                    yield p
                elif isinstance(v, (list, tuple)):
                    for item in v:
                        p2 = get_pos(item)
                        if p2 is not None:
                            yield p2

    def closest(src, points):
        best = None
        best_d = None
        for p in points:
            d = manhattan(src, p)
            if best_d is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    me = find_self(observation)

    # Gather possible categories across different tasks
    resource_points = []
    for k in ('resources', 'resource', 'food', 'ore', 'gold', 'materials', 'items'):
        resource_points.extend(list(iter_positions(observation.get(k))))

    enemy_points = []
    for k in ('enemies', 'enemy', 'opponents', 'opp', 'targets'):
        enemy_points.extend(list(iter_positions(observation.get(k))))

    territory_points = []
    for k in ('territory', 'frontier', 'capture_points', 'zones', 'cells'):
        territory_points.extend(list(iter_positions(observation.get(k))))

    bases = []
    for k in ('base', 'bases', 'home', 'homes', 'spawn'):
        bases.extend(list(iter_positions(observation.get(k))))

    obstacles = set()
    for k in ('walls', 'obstacles', 'blocked', 'rocks', 'trees', 'hazards'):
        for p in iter_positions(observation.get(k)):
            obstacles.add(p)

    # Prefer task-specific targets
    score_targets = []
    for p in resource_points:
        score_targets.append((p, 100))
    for p in territory_points:
        score_targets.append((p, 60))
    for p in enemy_points:
        score_targets.append((p, 80))

    # In pursuit/evasion, chase if advantaged or if nothing else
    if enemy_points and not resource_points and not territory_points:
        target, _ = closest(me, enemy_points)
    else:
        target = None
        best_score = None
        for p, w in score_targets:
            d = manhattan(me, p)
            s = w - d
            if best_score is None or s > best_score:
                best_score = s
                target = p

        if target is None:
            if bases:
                target, _ = closest(me, bases)
            elif enemy_points:
                target, _ = closest(me, enemy_points)
            else:
                return [0, 0]

    dx = clamp(target[0] - me[0])
    dy = clamp(target[1] - me[1])

    # Simple obstacle avoidance by trying alternate directions
    candidates = [(dx, dy)]
    if dx != 0 and dy != 0:
        candidates.append((dx, 0))
        candidates.append((0, dy))
    candidates.extend([(dx, 0), (0, dy), (0, 0)])

    for mx, my in candidates:
        nxt = (me[0] + mx, me[1] + my)
        if nxt not in obstacles:
            return [mx, my]

    return [0, 0]

